INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT127-S1-Q4$batch02$, 127, 1, 4, $batch02$Flaw$batch02$, $batch02$Columnist: Donating items to charity may be a sign of generosity, but any generosity it may demonstrate is rarely a permanent virtue, since most donors make donations only intermittently.$batch02$, $batch02$Which one of the following most accurately describes a flaw in the columnist’s argument?$batch02$, $batch02$C$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=127 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q4$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$The argument takes for granted that truly generous people are the most virtuous.$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q4$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$The argument attacks the character of those whose values are different from those of the columnist.$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q4$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$The argument takes for granted that a character trait is present only when manifested.$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q4$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$The argument generalizes from too small a sample of cases.$batch02$, $batch02$Not Sampling$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q4$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$The argument takes for granted that most people donate out of generosity.$batch02$, $batch02$Not Assumed$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q4$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q4$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$The generosity shown by donating is rarely a permanent virtue.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Most donors give only from time to time.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Does a trait vanish between the moments it shows? A pianist is still a pianist while asleep. A kind person is still kind while waiting for the bus. Donors who give now and then could be generous all the time and simply express it now and then. The columnist reads "intermittent giving" as "intermittent generosity."$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for the assumption that a trait exists only while it is being acted on.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT127-S1-Q4$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$Ranking generosity against other virtues has nothing to do with whether the generosity is permanent.$batch02$), ($batch02$B$batch02$, $batch02$The columnist does not attack anyone's character or contrast the donors' values with his own. He draws a conclusion about how lasting their generosity is.$batch02$), ($batch02$C$batch02$, $batch02$The columnist moves from "donors give only intermittently" to "their generosity is rarely permanent." That works only if generosity exists only when it shows up in a donation. Negate it, so that a trait can persist between its displays, and the argument falls apart.$batch02$), ($batch02$D$batch02$, $batch02$The evidence is about *most* donors. There is no small sample here; the problem is what intermittent giving says about character.$batch02$), ($batch02$E$batch02$, $batch02$The columnist hedges: donating "may be" a sign of generosity, and "any generosity it may demonstrate" is the subject. He does not need most donors to be generous. Negate (E) and his reasoning about permanence is unchanged.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT127-S1-Q4$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
